-- Phase 3a, migration weekly_brief (E4-5): the Monday brief.
--
-- Generated by `prisma migrate diff`, not edited. One new table and no change to an existing one,
-- so no row of the previous release is touched: WeeklyBrief (one row per user and week, the facts
-- of the brief as JSON). It is non-state (server/dataVersion.ts): written by the weekly job and by
-- the request that finds the current week without one, and read by no snapshot, memo or
-- deliverable. `revisionId` is set to null when the revision it describes is deleted with its plan.

-- CreateTable
CREATE TABLE "WeeklyBrief" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" TEXT NOT NULL,
    "weekStart" TEXT NOT NULL,
    "planId" TEXT,
    "revisionId" TEXT,
    "version" INTEGER NOT NULL,
    "facts" TEXT NOT NULL,
    "provisional" BOOLEAN NOT NULL DEFAULT false,
    "generatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "WeeklyBrief_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "WeeklyBrief_revisionId_fkey" FOREIGN KEY ("revisionId") REFERENCES "PlanRevision" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);

-- CreateIndex
CREATE UNIQUE INDEX "WeeklyBrief_revisionId_key" ON "WeeklyBrief"("revisionId");

-- CreateIndex
CREATE UNIQUE INDEX "WeeklyBrief_userId_weekStart_key" ON "WeeklyBrief"("userId", "weekStart");

